from content_helpers import code, output, choice, lesson, section, program
from content_06 import with_functions, example

def sections():
    return [section("memory", "10. Ссылки, указатели и время жизни", "Различайте объект, имя и доступ к живому объекту.", [
        lesson("references", "Ссылки", "Разрешите функции изменять переданный объект явно.",
            "int& alias = value; создаёт ссылку — другое имя существующего int. Она должна быть инициализирована; присваивание alias=7 меняет сам value. Ссылку нельзя затем «переназначить»: alias=other копирует значение other в связанный объект.\n\nПараметр int& позволяет функции работать с исходной переменной: void add(int& value,int bonus). Вызов требует подходящего объекта, не произвольного временного выражения. const std::vector<int>& даёт доступ без копирования и без права менять элементы через эту ссылку. const означает ограничение изменения через данный путь доступа.\n\nВ range for запись for (int& value : values) позволяет менять элементы на месте. Отличайте & в объявлении ссылки от операции получения адреса в следующем уроке.",
            example('void add(int& value, int bonus) { value += bonus; }', 'int energy = 3;\nadd(energy, 4);\nstd::cout << energy;'),
            "Ссылка не владеет объектом и сама не продлевает жизнь произвольного ранее созданного объекта. Для простых ссылок этого урока исходный объект живёт дольше использования. Передача по ссылке — не автоматическое обещание безопасности.",
            "int — копия, int& — доступ к исходному объекту, const T& — чтение без копии через эту ссылку.", [
                with_functions(code("swap", "Обмен через функцию", 'Напишите void exchange(int& a,int& b), меняющую значения местами. main читает a,b (−100…100), вызывает функцию и выводит новые значения.', 'int a = 0, b = 0;\nstd::cin >> a >> b;\nexchange(a, b);\nstd::cout << a << " " << b;', [("3 8", "8 3"), ("7 7", "7 7"), ("-5 12", "12 -5"), ("-100 100", "100 -100"), ("0 0", "0 0")], ["Оба параметра должны быть ссылками.", "Используйте временный int для сохранения исходного a."], "Если убрать &, обмен произошёл бы только между копиями."), 'void exchange(int& a, int& b) {\n    int saved = a; a = b; b = saved;\n}'),
                with_functions(code("sum", "Сумма без копирования", 'Напишите int total(const std::vector<int>& values), возвращающую сумму элементов. Ввод main: n (0…100) и n чисел (−100…100). Выведите total.', 'int n = 0;\nstd::cin >> n;\nstd::vector<int> v(n);\nfor (int i = 0; i < n; ++i) { std::cin >> v[i]; }\nstd::cout << total(v);', [("3 1 -2 7", "6"), ("0", "0"), ("1 5", "5"), ("4 -1 -2 -3 -4", "-10"), ("5 100 -100 0 50 -50", "0"), ("3 0 0 0", "0")], ["const-ссылка не создаёт копию всего vector.", "Внутри заведите sum и переберите значения для чтения."], "Пустой диапазон даёт сумму 0, не требует чтения первого элемента.", headers="iostream vector"), 'int total(const std::vector<int>& values) {\n    int sum = 0;\n    for (int x : values) { sum += x; }\n    return sum;\n}'),
                output("alias", "Ссылка не переназначается", 'int a = 3, b = 9;\nint& alias = a;\nalias = b;\nb = 2;\nstd::cout << a << " " << alias;', "9 9", ["alias продолжает обозначать a.", "Присваивание копирует значение b в a в тот момент."], "Изменение b позже не меняет a и не переключает ссылку."),
                code("increment", "Обновление через range for", 'Ввод: n (0…100), затем n чисел (−100…100). Через for(int& value : v) увеличьте каждый элемент на 1 и выведите через пробел.', 'int n = 0;\nstd::cin >> n;\nstd::vector<int> v(n);\nfor (int i = 0; i < n; ++i) { std::cin >> v[i]; }\nfor (int& value : v) { ++value; }\nfor (int i = 0; i < n; ++i) {\n    if (i > 0) { std::cout << " "; }\n    std::cout << v[i];\n}', [("3 1 2 -1", "2 3 0"), ("0", ""), ("1 5", "6"), ("4 -2 -1 0 1", "-1 0 1 2"), ("3 100 100 -100", "101 101 -99")], ["Ссылка value должна быть объявлена с &.", "После изменения выводите исходный vector."], "Каждая итерация связывает новую ссылку с очередным элементом.", headers="iostream vector")
            ], ["ссылки", "const reference", "передача параметров"]),
        lesson("pointers", "Адреса и указатели", "Проверьте наличие объекта перед обращением.",
            "&value получает адрес объекта. int* pointer = &value; сохраняет указатель на int. *pointer обращается к самому объекту: *pointer=7 меняет value. Указатель можно переназначать на другой живой объект. nullptr обозначает отсутствие указателя на объект. Перед доступом через потенциально пустой указатель проверяйте pointer != nullptr.\n\nОбъявление int* p и выражение *p имеют разные роли: первое задаёт тип, второе разыменовывает. Не путайте адрес и значение. Адреса меняются между запусками и не имеют фиксированного ожидаемого текста, поэтому задачи не требуют угадать напечатанный адрес. Сырые указатели здесь не владеют памятью: все объекты созданы обычными локальными переменными.",
            program('int value = 3;\nint* p = &value;\n*p += 4;\nstd::cout << value;'),
            "Проверка на nullptr не доказывает, что непустой указатель всё ещё обозначает живой объект. После окончания времени жизни объекта указатель может остаться непустым, но чтение через него уже недопустимо. Время жизни важнее внешнего вида адреса.",
            "& получает адрес, * обращается к объекту. nullptr проверяется до доступа, но живость тоже обязательна.", [
                code("change", "Измените через адрес", 'Ввод: int value и bonus (−100…100). Создайте int* p=&value, измените value через *p прибавлением bonus и выведите value.', 'int value = 0, bonus = 0;\nstd::cin >> value >> bonus;\nint* p = &value;\n*p += bonus;\nstd::cout << value;', [("3 7", "10"), ("-4 2", "-2"), ("0 0", "0"), ("-100 -100", "-200"), ("100 100", "200"), ("0 -50", "-50")], ["Адрес берётся у переменной value.", "Запись *p += bonus меняет объект по адресу."], "Сам указатель не является копией целого значения объекта."),
                code("select", "Выбранный датчик", 'Ввод: a,b (−100…100), select (0 или 1). Создайте указатель на a при select=0, на b при 1. Увеличьте выбранное значение через указатель на 1, выведите a и b.', 'int a = 0, b = 0, select = 0;\nstd::cin >> a >> b >> select;\nint* p = nullptr;\nif (select == 0) { p = &a; }\nelse { p = &b; }\n++(*p);\nstd::cout << a << " " << b;', [("3 8 0", "4 8"), ("3 8 1", "3 9"), ("-5 5 0", "-4 5"), ("-5 5 1", "-5 6"), ("100 -100 0", "101 -100"), ("0 0 1", "0 1")], ["Переназначать нужно сам p, а менять — *p.", "Обе ветви устанавливают адрес до разыменования."], "Скобки в ++(*p) подчёркивают, что увеличивается объект, не адрес."),
                choice("null", "Что гарантирует непустота?", 'Если p != nullptr, достаточно ли этого всегда для безопасного чтения *p?', ["Нет, указатель может быть висячим после окончания жизни объекта", "Да, непустой адрес всегда безопасен", "Да, если тип int"], 0, ["Объект мог перестать существовать.", "nullptr — только один из возможных недопустимых для чтения случаев."], "Сырой указатель не хранит автоматическое доказательство живости объекта."),
                with_functions(code("optional", "Необязательное показание", 'Напишите int readOrZero(const int* p), возвращающую 0 при nullptr и *p иначе. main читает present (0/1) и value (−100…100), передаёт nullptr при 0, &value при 1 и выводит результат.', 'int present = 0, value = 0;\nstd::cin >> present >> value;\nconst int* p = nullptr;\nif (present == 1) { p = &value; }\nstd::cout << readOrZero(p);', [("0 7", "0"), ("1 -5", "-5"), ("0 0", "0"), ("1 0", "0"), ("1 100", "100"), ("0 -100", "0")], ["Проверка должна предшествовать чтению.", "Сначала if(p==nullptr) return 0, затем return *p."], "const int* запрещает менять int через этот указатель; сам указатель может хранить разные адреса."), 'int readOrZero(const int* p) {\n    if (p == nullptr) { return 0; }\n    return *p;\n}')
            ], ["указатели", "nullptr", "адреса"]),
        lesson("lifetime", "Время жизни и границы", "Не возвращайте доступ к уже исчезнувшему объекту.",
            "Обычный локальный объект существует до выхода из своего блока. Указатель или ссылка, сохранённые дольше, не делают этот объект вечным. Нельзя возвращать из функции int* на её локальный int и потом читать его в вызывающем коде. Верните int по значению: возвращённое значение создаёт самостоятельный результат.\n\nПонятие «стек» — удобная модель реализации локальных вызовов, но стандарт описывает длительность хранения и время жизни, не требуя именно конкретной аппаратной структуры. Динамическая память может жить дольше вызова; управление ею изучим отдельно.\n\nДля массива указатель можно сдвигать только в пределах допустимого массива и позиции за концом. Указатель за концом допустим для сравнения/обхода, не для чтения элемента.",
            example('int answer() {\n    int local = 42;\n    return local;\n}', 'int value = answer();\nstd::cout << value;'),
            "После завершения времени жизни нельзя обосновать безопасность тем, что «старое число ещё лежит в памяти». Наблюдение одного запуска не создаёт гарантии стандарта. Для учебных примеров с UB задаём вопрос о причине ошибки, а не о точном выводе.",
            "Возвращайте значения, когда нужен результат. Ссылка или указатель должны использоваться только при живом исходном объекте.", [
                with_functions(code("value", "Безопасный возврат", 'Напишите int nextValue(int n), которая создаёт локальный result=n+1 и возвращает его по значению. main читает n (−100…100) и выводит вызов.', 'int n = 0;\nstd::cin >> n;\nstd::cout << nextValue(n);', [("7", "8"), ("-1", "0"), ("-100", "-99"), ("99", "100"), ("0", "1"), ("100", "101")], ["Возвращаемый тип — int, не int* и не int&.", "return result передаёт значение, не доступ к локальному объекту."], "Результат вызова остаётся пригодным после завершения функции."), 'int nextValue(int n) { int result = n + 1; return result; }'),
                code("block", "Копия переживает блок", 'Ввод: n (−100…100). Объявите result снаружи блока, внутри создайте local=n*2, скопируйте local в result. После блока выведите result.', 'int n = 0;\nstd::cin >> n;\nint result = 0;\n{\n    int local = n * 2;\n    result = local;\n}\nstd::cout << result;', [("7", "14"), ("0", "0"), ("-5", "-10"), ("100", "200"), ("-100", "-200"), ("1", "2")], ["Сохраняется значение, не адрес local.", "Внешний result продолжает жить после закрытия внутреннего блока."], "Копирование простого int отделяет время жизни результата от источника."),
                choice("dangling", "Возврат адреса локальной", 'Функция возвращает адрес своего локального int. Почему последующее чтение через этот адрес недопустимо?', ["Локальный объект уже закончил время жизни", "Любой адрес запрещено возвращать", "Указатель автоматически становится nullptr"], 0, ["Проблема не в синтаксисе return, а в том, на что он указывает.", "Завершение функции заканчивает жизнь её обычной локальной переменной."], "Указатель не обязан обнулиться. Чтение через него не имеет гарантированного результата."),
                output("scopes", "Внутреннее имя", 'int x = 3;\n{\n    int x = 8;\n    std::cout << x << " ";\n}\nstd::cout << x;', "8 3", ["Внутренний x — другой объект.", "После блока снова видно внешнее имя."], "Затенение имени не изменяет исходный объект, хотя может ухудшать читаемость.")
            ], ["время жизни", "висячие указатели", "хранение"]),
        lesson("pointerarray", "Указатель и диапазон", "Пройдите массив до конца, не читая за ним.",
            "Для int data[3] имя data в большинстве выражений преобразуется в указатель на первый элемент. int* p=data; и int* end=data+3; задают полуинтервал. ++p переходит к следующему элементу этого массива, а не к произвольному байту. Пока p!=end, можно читать *p. После p==end чтение недопустимо.\n\nПараметр функции, записанный как T data[N], преобразуется к типу T*: запись N сама по себе не проверяет длину переданного массива. Размер массива не содержится в сыром указателе. Функция int sum(const int* data,int size) должна получить длину отдельно и соблюдать её контракт. Для новых интерфейсов std::vector или std::array обычно понятнее; изучение указателей не означает рекомендацию заменить ими контейнеры. Нельзя вычитать указатели на несвязанные объекты для получения полезного расстояния.\n\nТип массива и тип указателя — разные вещи: в области объявления int data[5] sizeof(data)/sizeof(data[0]) даёт число элементов, но тот же расчёт для параметра int* data уже не имеет смысла. void* хранит адрес без типа элемента и разыменовывается только после явного приведения к конкретному типу. Указатель на указатель T** хранит адрес другого указателя: так строят массивы указателей на строки в динамической памяти — этот приём разберём в разделе о динамическом времени хранения.",
            program('int data[3] = {2, 4, 6};\nint sum = 0;\nfor (const int* p = data; p != data + 3; ++p) { sum += *p; }\nstd::cout << sum;'),
            "Арифметика указателей определена относительно одного массива и допустимой позиции за концом. Это не универсальный калькулятор адресов. Даже если два разных локальных объекта оказались рядом, стандарт не превращает их в массив.",
            "Указателю нужна граница диапазона. Позиция за концом завершает обход, но не обозначает живой элемент.", [
                code("sum", "Обход трёх датчиков", 'Ввод: три int (−100…100). Сохраните во встроенный массив из трёх элементов. Сложите через указатель p от data до data+3 и выведите сумму.', 'int data[3] = {};\nfor (int i = 0; i < 3; ++i) { std::cin >> data[i]; }\nint sum = 0;\nfor (const int* p = data; p != data + 3; ++p) { sum += *p; }\nstd::cout << sum;', [("1 -2 7", "6"), ("0 0 0", "0"), ("-1 -2 -3", "-6"), ("100 100 100", "300"), ("-100 0 100", "0")], ["end указывает за третий элемент.", "Проверяйте p!=end до чтения *p."], "Ровно три допустимых разыменования соответствуют трём элементам."),
                code("change", "Изменение через диапазон", 'Ввод: три int (−100…100). Через указательный цикл увеличьте элементы массива на 2 и выведите их через пробел.', 'int data[3] = {};\nfor (int i = 0; i < 3; ++i) { std::cin >> data[i]; }\nfor (int* p = data; p != data + 3; ++p) { *p += 2; }\nstd::cout << data[0] << " " << data[1] << " " << data[2];', [("1 2 3", "3 4 5"), ("-2 -2 -2", "0 0 0"), ("0 0 0", "2 2 2"), ("100 100 100", "102 102 102"), ("-100 0 100", "-98 2 102")], ["Для изменения указатель не должен быть const int*.", "Прибавляйте к *p, а ++p оставьте шагом цикла."], "Изменение значения и перемещение указателя — две разные операции."),
                choice("end", "Позиция за концом", 'Можно ли хранить указатель data+3 для массива из трёх int и читать *(data+3)?', ["Хранить границу можно, читать как элемент нельзя", "Оба действия всегда запрещены", "Оба действия всегда безопасны"], 0, ["Полуинтервал допускает граничную позицию.", "Но четвёртого элемента нет."], "Различайте создание граничного указателя и обращение к несуществующему объекту."),
                with_functions(code("function", "Функция над массивом", 'Напишите int total(const int* data,int size), складывающую size элементов. main читает ровно четыре int (−100…100) в массив и выводит total(data,4).', 'int data[4] = {};\nfor (int i = 0; i < 4; ++i) { std::cin >> data[i]; }\nstd::cout << total(data, 4);', [("1 2 3 4", "10"), ("-1 -2 -3 -4", "-10"), ("0 0 0 0", "0"), ("100 100 100 100", "400"), ("-100 100 -100 100", "0"), ("5 -5 5 -5", "0")], ["Длина приходит отдельным параметром.", "Суммируйте data[i] для 0<=i<size."], "Функция не умеет вывести длину исходного массива из одного указателя."), 'int total(const int* data, int size) {\n    int sum = 0;\n    for (int i = 0; i < size; ++i) { sum += data[i]; }\n    return sum;\n}'),
                choice("sizeofarray", "Размер массива через sizeof", 'Для int data[5] в этом же блоке вычислено data[0], data[4]... Сколько элементов даст выражение sizeof(data) / sizeof(data[0])?', ["5 — пока data всё ещё имеет тип массива", "Всегда 1, потому что data — указатель", "Неопределённое количество, зависит от длины имени"], 0, ["В области объявления data имеет тип int[5].", "Осторожно: тот же расчёт после передачи параметром int* data уже не работает."], "Массив и указатель — разные типы: в области объявления массива sizeof даёт размер всего массива, а после преобразования к параметру-указателю формула теряет смысл."),
                choice("voidstar", "Не типизированный адрес", 'Что нужно, чтобы прочитать значение по void* p?', ["Ничего: *p уже работает", "Явно привести p к указателю на конкретный тип", "Присвоить p = nullptr перед чтением"], 1, ["void* хранит адрес без типа элемента.", "Компилятор не знает, сколько байтов читать и как их трактовать."], "void* — адрес без типа: разыменовать его напрямую нельзя, сначала укажите конкретный тип.")
            ], ["арифметика указателей", "диапазоны", "массивы", "void*"])
    ])]
